"use client";

import Image from "next/image";
import Link from "next/link";
import { useEffect, useState } from "react";
import {
  ArrowLeft,
  ExternalLink,
  Copy,
  CheckCircle2,
  Globe,
  TrendingUp,
  DollarSign,
  Users,
  Calendar,
} from "lucide-react";
import { motion } from "framer-motion";
import { usePrivy } from "@privy-io/react-auth";
import { Button } from "@/components/ui/button";
import { formatWalletAddress } from "@/lib/wallet-privy";
import { toast } from "sonner";
import { ethers } from "ethers";
import { SwapInterface } from "@/components/SwapInterface";

// CL Pool ABI - minimal functions needed
const CL_POOL_ABI = [
  "function liquidity() view returns (uint256)",
  "function token0() view returns (address)",
  "function token1() view returns (address)",
];

// ERC-20 ABI for token info
const ERC20_ABI = [
  "function symbol() view returns (string)",
  "function name() view returns (string)",
  "function decimals() view returns (uint8)",
  "function totalSupply() view returns (uint256)",
];

interface PoolData {
  liquidity: string | null;
  token0: string | null;
  token1: string | null;
  token0Symbol: string | null;
  token1Symbol: string | null;
  token0Name: string | null;
  token1Name: string | null;
}

interface PresaleData {
  _id: string;
  appName: string;
  appLogo?: string | null;
  tickerName: string;
  description?: string;
  erc20Symbol?: string;
  erc20Name?: string;
  appXHandle?: string;
  isXConnected?: boolean;
  appLink?: string;
  creator?: string;
  totalRaised?: string;
  contributorCount?: number;
  contractStartTime?: number;
  endTime?: number;
  crowdfundAddress?: string;
  poolLauncherToken?: string | null;
  tokenToPair?: string | null;
  projectToken?: string | null;
}

type Props = { poolAddress: string };

export default function PoolDetailsClient({ poolAddress }: Props) {
  const [poolData, setPoolData] = useState<PoolData | null>(null);
  const [presaleData, setPresaleData] = useState<PresaleData | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [copiedAddress, setCopiedAddress] = useState<string | null>(null);

  const { authenticated } = usePrivy();

  // RPC endpoints with fallbacks
  const rpcUrls = [
    "https://base.llamarpc.com",
    "https://base-mainnet.g.alchemy.com/v2/demo",
    "https://mainnet.base.org",
    "https://1rpc.io/base",
  ];

  // Get provider with fallback
  const getProvider = async (): Promise<ethers.JsonRpcProvider> => {
    let lastError: Error | null = null;
    for (const url of rpcUrls) {
      try {
        const provider = new ethers.JsonRpcProvider(url);
        await provider.getBlockNumber(); // Test connection
        return provider;
      } catch (err) {
        lastError = err as Error;
        continue;
      }
    }
    throw lastError || new Error("All RPC endpoints failed");
  };

  // Fetch pool data from contract
  useEffect(() => {
    let isActive = true;
    const fetchPoolData = async () => {
      setIsLoading(true);
      setError(null);

      try {
        const provider = await getProvider();
        const poolContract = new ethers.Contract(poolAddress, CL_POOL_ABI, provider);

        // Fetch pool data
        const [liquidity, token0, token1] = await Promise.all([
          poolContract.liquidity().catch(() => null),
          poolContract.token0().catch(() => null),
          poolContract.token1().catch(() => null),
        ]);

        if (!isActive) return;

        // Fetch token info
        let token0Symbol: string | null = null;
        let token1Symbol: string | null = null;
        let token0Name: string | null = null;
        let token1Name: string | null = null;

        if (token0) {
          try {
            const token0Contract = new ethers.Contract(token0, ERC20_ABI, provider);
            [token0Symbol, token0Name] = await Promise.all([
              token0Contract.symbol().catch(() => null),
              token0Contract.name().catch(() => null),
            ]);
          } catch (err) {
            console.warn("Failed to fetch token0 info:", err);
          }
        }

        if (token1) {
          try {
            const token1Contract = new ethers.Contract(token1, ERC20_ABI, provider);
            [token1Symbol, token1Name] = await Promise.all([
              token1Contract.symbol().catch(() => null),
              token1Contract.name().catch(() => null),
            ]);
          } catch (err) {
            console.warn("Failed to fetch token1 info:", err);
          }
        }

        // Format liquidity (CL pool liquidity is in USDC, 6 decimals)
        let formattedLiquidity: string | null = null;
        if (liquidity) {
          const liquidityBigInt = BigInt(liquidity.toString());
          // Convert from USDC (6 decimals) for display
          const liquidityUSDC = Number(liquidityBigInt) / 1e6;
          formattedLiquidity = `$${liquidityUSDC.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        }

        setPoolData({
          liquidity: formattedLiquidity,
          token0,
          token1,
          token0Symbol,
          token1Symbol,
          token0Name,
          token1Name,
        });

        // Fetch presale data from backend
        const backendUrl = process.env.NEXT_PUBLIC_BACKEND_URL || "http://localhost:3001";
        const response = await fetch(`${backendUrl}/api/presales`, {
          headers: { Accept: "application/json" },
          cache: "no-store",
        });

        if (response.ok) {
          const payload = await response.json();
          const presale = (payload.data || []).find(
            (p: any) => p.pool === poolAddress || p.liquidityPool === poolAddress
          );

          if (presale) {
            // Build logo URL
            let logoUrl: string | null = null;
            if (presale.appLogo) {
              if (typeof presale.appLogo === "string") {
                if (presale.appLogo.startsWith("http")) {
                  logoUrl = presale.appLogo;
                } else {
                  const logoPath = presale.appLogo.startsWith("/") ? presale.appLogo : `/${presale.appLogo}`;
                  logoUrl = `${backendUrl}${logoPath}`;
                }
              }
            }

            setPresaleData({
              _id: presale._id,
              appName: presale.appName || "Unknown",
              appLogo: logoUrl,
              tickerName: presale.tickerName || "TOKEN",
              description: presale.description || "",
              erc20Symbol: presale.erc20Symbol,
              erc20Name: presale.erc20Name,
              appXHandle: presale.appXHandle,
              isXConnected: presale.isXConnected || false,
              appLink: presale.appLink,
              creator: presale.creator,
              totalRaised: presale.totalRaised,
              contributorCount: presale.contributorCount || 0,
              contractStartTime: presale.contractStartTime,
              endTime: presale.endTime,
              crowdfundAddress: presale.crowdfundAddress,
              poolLauncherToken: presale.poolLauncherToken,
              tokenToPair: presale.tokenToPair,
              projectToken: presale.projectToken,
            });
          }
        }
      } catch (err) {
        if (isActive) {
          setError(err instanceof Error ? err.message : "Failed to load pool data");
          console.error("Error fetching pool data:", err);
        }
      } finally {
        if (isActive) setIsLoading(false);
      }
    };

    fetchPoolData();
    return () => {
      isActive = false;
    };
  }, [poolAddress]);

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    setCopiedAddress(label);
    toast.success("Address copied to clipboard");
    setTimeout(() => setCopiedAddress(null), 2000);
  };

  const formatUSDC = (value: string | undefined): string => {
    if (!value) return "$0.00";
    try {
      const num = BigInt(value);
      const usdc = Number(num) / 1e6;
      return `$${usdc.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    } catch {
      return "$0.00";
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#EC4E02] mx-auto mb-4"></div>
          <p className="text-white/60">Loading pool data...</p>
        </div>
      </div>
    );
  }

  if (error || !poolData) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-500 mb-4">Failed to load pool data</p>
          <p className="text-white/60 mb-4">{error || "Pool not found"}</p>
          <Link href="/">
            <Button variant="outline">Go Back</Button>
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white">
      {/* Header */}
      <div className="border-b border-white/10 bg-[#0F0F10]">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <Link href="/" className="inline-flex items-center gap-2 text-white/60 hover:text-white transition-colors">
            <ArrowLeft className="h-4 w-4" />
            <span>Back to Dashboard</span>
          </Link>
        </div>
      </div>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Main Content */}
          <div className="lg:col-span-2 space-y-6">
            {/* Pool Header */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <div className="flex items-start gap-4">
                {presaleData?.appLogo && (
                  <div className="relative h-16 w-16 rounded-xl overflow-hidden border border-white/10">
                    <Image
                      src={presaleData.appLogo}
                      alt={presaleData.appName}
                      fill
                      className="object-cover"
                      unoptimized
                    />
                  </div>
                )}
                <div className="flex-1">
                  <h1 className="text-2xl font-bold text-white mb-2">
                    {presaleData?.appName || "Pool"} ({presaleData?.tickerName || "TOKEN"})
                  </h1>
                  {presaleData?.description && (
                    <p className="text-white/60 text-sm mb-4">{presaleData.description}</p>
                  )}
                  <div className="flex items-center gap-4 text-sm">
                    {presaleData?.appLink && (
                      <a
                        href={presaleData.appLink}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                      >
                        <Globe className="h-4 w-4" />
                        <span>Website</span>
                        <ExternalLink className="h-3 w-3" />
                      </a>
                    )}
                    {presaleData?.appXHandle && (
                      <a
                        href={`https://x.com/${presaleData.appXHandle}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                      >
                        <span>@{presaleData.appXHandle}</span>
                        <ExternalLink className="h-3 w-3" />
                      </a>
                    )}
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Pool Info */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.1 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Pool Information</h2>
              <div className="space-y-4">
                <div className="flex items-center justify-between py-3 border-b border-white/5">
                  <span className="text-white/60">Liquidity</span>
                  <span className="text-white font-bold">{poolData.liquidity || "--"}</span>
                </div>
                <div className="flex items-center justify-between py-3 border-b border-white/5">
                  <span className="text-white/60">Token 0</span>
                  <div className="flex items-center gap-2">
                    {poolData.token0Symbol && (
                      <span className="text-white/80 text-sm font-semibold">
                        {poolData.token0Symbol}
                      </span>
                    )}
                    <span className="text-white font-mono text-sm">
                      {poolData.token0 ? formatWalletAddress(poolData.token0) : "--"}
                    </span>
                    {poolData.token0 && (
                      <>
                        <button
                          onClick={() => copyToClipboard(poolData.token0!, "token0")}
                          className="text-white/40 hover:text-white transition-colors"
                        >
                          {copiedAddress === "token0" ? (
                            <CheckCircle2 className="h-4 w-4" />
                          ) : (
                            <Copy className="h-4 w-4" />
                          )}
                        </button>
                        <a
                          href={`https://basescan.org/address/${poolData.token0}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </>
                    )}
                  </div>
                </div>
                <div className="flex items-center justify-between py-3 border-b border-white/5">
                  <span className="text-white/60">Token 1</span>
                  <div className="flex items-center gap-2">
                    {poolData.token1Symbol && (
                      <span className="text-white/80 text-sm font-semibold">
                        {poolData.token1Symbol}
                      </span>
                    )}
                    <span className="text-white font-mono text-sm">
                      {poolData.token1 ? formatWalletAddress(poolData.token1) : "--"}
                    </span>
                    {poolData.token1 && (
                      <>
                        <button
                          onClick={() => copyToClipboard(poolData.token1!, "token1")}
                          className="text-white/40 hover:text-white transition-colors"
                        >
                          {copiedAddress === "token1" ? (
                            <CheckCircle2 className="h-4 w-4" />
                          ) : (
                            <Copy className="h-4 w-4" />
                          )}
                        </button>
                        <a
                          href={`https://basescan.org/address/${poolData.token1}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </>
                    )}
                  </div>
                </div>
                <div className="flex items-center justify-between py-3">
                  <span className="text-white/60">Pool Address</span>
                  <div className="flex items-center gap-2">
                    <span className="text-white font-mono text-sm">{formatWalletAddress(poolAddress)}</span>
                    <button
                      onClick={() => copyToClipboard(poolAddress, "pool")}
                      className="text-white/40 hover:text-white transition-colors"
                    >
                      {copiedAddress === "pool" ? (
                        <CheckCircle2 className="h-4 w-4" />
                      ) : (
                        <Copy className="h-4 w-4" />
                      )}
                    </button>
                    <a
                      href={`https://basescan.org/address/${poolAddress}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                    >
                      <ExternalLink className="h-4 w-4" />
                    </a>
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Presale Info (if available) */}
            {presaleData && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: 0.2 }}
                className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
              >
                <h2 className="text-xl font-bold text-white mb-4">Presale Information</h2>
                <div className="space-y-4">
                  {presaleData.totalRaised && (
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60 flex items-center gap-2">
                        <DollarSign className="h-4 w-4" />
                        Total Raised
                      </span>
                      <span className="text-white font-bold">{formatUSDC(presaleData.totalRaised)}</span>
                    </div>
                  )}
                  {presaleData.contributorCount !== undefined && (
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60 flex items-center gap-2">
                        <Users className="h-4 w-4" />
                        Contributors
                      </span>
                      <span className="text-white font-bold">{presaleData.contributorCount}</span>
                    </div>
                  )}
                  {presaleData.creator && (
                    <div className="flex items-center justify-between py-3 border-b border-white/5">
                      <span className="text-white/60">Creator</span>
                      <div className="flex items-center gap-2">
                        <span className="text-white font-mono text-sm">{formatWalletAddress(presaleData.creator)}</span>
                        <a
                          href={`https://basescan.org/address/${presaleData.creator}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </div>
                    </div>
                  )}
                  {presaleData.crowdfundAddress && (
                    <div className="flex items-center justify-between py-3">
                      <span className="text-white/60">Crowdfund Contract</span>
                      <div className="flex items-center gap-2">
                        <span className="text-white font-mono text-sm">
                          {formatWalletAddress(presaleData.crowdfundAddress)}
                        </span>
                        <a
                          href={`https://basescan.org/address/${presaleData.crowdfundAddress}`}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-[#EC4E02] hover:text-[#EC4E02]/80 transition-colors"
                        >
                          <ExternalLink className="h-4 w-4" />
                        </a>
                      </div>
                    </div>
                  )}
                </div>
              </motion.div>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Swap Interface */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Swap</h2>
              {presaleData?.projectToken ? (
                <SwapInterface
                  tokenAddress={presaleData.projectToken}
                  tokenSymbol={presaleData.tickerName || presaleData.erc20Symbol || "TOKEN"}
                  poolCreated={true}
                  poolAddress={poolAddress}
                  crowdfundAddress={presaleData.crowdfundAddress || null}
                />
              ) : (
                <div className="text-center py-8 text-white/60">
                  <p>Loading token information...</p>
                </div>
              )}
            </motion.div>

            {/* Quick Stats */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.4 }}
              className="bg-[#0F0F10] border border-white/10 rounded-2xl p-6"
            >
              <h2 className="text-xl font-bold text-white mb-4">Quick Stats</h2>
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-sm">Status</span>
                  <span className="px-2 py-1 rounded bg-green-500/20 text-green-500 text-xs font-bold">Active</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-white/60 text-sm">Network</span>
                  <span className="text-white text-sm font-bold">Base</span>
                </div>
              </div>
            </motion.div>
          </div>
        </div>
      </main>
    </div>
  );
}
